#!/usr/bin/env python3
"""Apply TerraVeil Stage 3 repeatable demo/risk engine. Run from repo root."""
from pathlib import Path

ROOT = Path.cwd()
FILES = {
    "database": ROOT / "database.py",
    "telemetry": ROOT / "telemetry.py",
    "app": ROOT / "app.py",
    "appjs": ROOT / "static" / "js" / "app.js",
    "index": ROOT / "templates" / "index.html",
}
for name, path in FILES.items():
    if not path.exists():
        raise SystemExit(f"Missing {name}: {path}. Run from TerraVeil repo root.")

def replace_once(text, old, new, label):
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected 1 match, found {count}")
    return text.replace(old, new, 1)

def replace_between(text, start_marker, end_marker, replacement, label):
    start = text.find(start_marker)
    if start < 0:
        raise RuntimeError(f"{label}: start marker not found")
    end = text.find(end_marker, start)
    if end < 0:
        raise RuntimeError(f"{label}: end marker not found")
    return text[:start] + replacement + text[end:]

def indent_block(block, spaces=4):
    prefix = " " * spaces
    return "".join(prefix + line if line.strip() else line for line in block.splitlines(True))

def save(path, original, updated):
    if updated == original:
        print(f"[UNCHANGED] {path}")
    else:
        path.write_text(updated)
        print(f"[UPDATED]   {path}")

# database.py
